// 规则：
// 1. weightKg <= 0 或 !Number.isFinite(weightKg) 抛 RangeError
// 2. weightKg <= 1 基础运费 10 元；超过 1kg 部分按 Math.ceil(weightKg - 1) * 4 加收
// 3. isRemote === true 额外加 15 元
export function calcShippingFee(weightKg, isRemote = false) {
  if (!Number.isFinite(weightKg) || weightKg < 0) {
    throw new RangeError('INVALID_WEIGHT');
  }
  const extraKg = weightKg > 1 ? Math.ceil(weightKg - 1) : 0;
  const base = 10 + extraKg * 4;
  return isRemote ? base + 15 : base;
}

import test from 'node:test';
import assert from 'node:assert/strict';
import {calcShippingFee} from '../src/shipping.mjs';

test('1kg normal shipping', () => {
  assert.equal(calcShippingFee(1, false), 10);
});

export function mergeConfig(defaults = {}, overrides = {}) {
  const out = {...defaults};
  for (const [k, v] of Object.entries(overrides || {})) {
    if (v) {
      out[k] = v;
    }
  }
  return out;
}

import test from 'node:test';
import assert from 'node:assert/strict';
import {mergeConfig} from '../src/merge-config.mjs';

test('overrides string field', () => {
  assert.deepEqual(mergeConfig({host: 'localhost'}, {host: '127.0.0.1'}), {host: '127.0.0.1'});
});
